@startuml

class Patient {
  + Name : string
}

class Family {
  + Name : string
}

class Doctor {
  + Name : string
}

class Receptionist {}

class Nurse {}

class Appointment {
  + Date : date
  + Time : time
}

class Visit {
  + Diagnosis : string
  + Treatment : string
}

class Medication {
  + Name : string
}

class History {
  + Content : string
}

Family "1" -- "1..*" Patient : contains
Family "1" -- "0..1" Doctor : has primary care physician
Patient "1" -- "0..*" Appointment : attends
Patient "1" -- "0..*" Visit : undergoes
Patient "1" -- "0..*" History : has
Doctor "1" -- "0..*" Appointment : attends
Doctor "1" -- "0..*" Visit : performs
Doctor "1" -- "0..*" Visit : performs
Nurse "1" -- "0..*" Visit : records
Nurse "1" -- "0..*" Appointment : schedules
Receptionist "1" -- "0..*" Appointment : schedules
Receptionist "1" -- "0..*" Patient : registers
Visit "1" *-- "0..*" Medication : prescribes
Visit "1" *-- "0..*" History : contains

@enduml

